const TYPES = ['mcq', 'info', 'ppt'];
const staticData = $getWorkflowStaticData('global');
if (typeof staticData.typeIndex !== 'number') staticData.typeIndex = 0;
const cardType = TYPES[staticData.typeIndex % TYPES.length];
staticData.typeIndex = (staticData.typeIndex + 1) % TYPES.length;

if (!Array.isArray(staticData.usedTopics)) staticData.usedTopics = [];
const recentTopics = staticData.usedTopics.slice(-15).join(', ') || 'কিছুই না';

let systemPrompt, userPrompt;

if (cardType === 'mcq') {
  systemPrompt = `তুমি Questionhut নামক একটি বাংলাদেশি শিক্ষামূলক ইউটিউব চ্যানেলের জন্য BCS মানের কুইজ প্রশ্ন তৈরি করো। একটি সিঙ্গেল MCQ প্রশ্ন বাংলায় লিখবে, ৪টি অপশন সহ (অপশনের টেক্সটে ক/খ/গ/ঘ লেবেল যোগ করবে না, শুধু answer)। প্রশ্ন তথ্যভিত্তিক, সঠিক ও প্রমিত বাংলা ভাষায় স্পষ্টভাবে লেখা হতে হবে। নিচের বিষয়গুলো সম্প্রতি ব্যবহার করা হয়েছে, এগুলো এড়িয়ে নতুন কিছু বাছাই করো: ${recentTopics}। শুধুমাত্র বৈধ JSON আকারে উত্তর দাও, অন্য কোনো টেক্সট ছাড়া, এই কাঠামোতে: {"question":"...","options":["...","...","...","..."],"correctIndex":0,"topic":"সংক্ষিপ্ত বিষয় ট্যাগ (ইংরেজি)"}`;
  userPrompt = 'একটি নতুন BCS সাধারণ জ্ঞান MCQ প্রশ্ন তৈরি করো।';
} else if (cardType === 'info') {
  systemPrompt = `তুমি Questionhut ইউটিউব চ্যানেলের জন্য ছোট, চমকপ্রদ তথ্য (fun fact) লেখো — বাংলাদেশ, বিজ্ঞান, ইতিহাস বা সাধারণ জ্ঞান বিষয়ে। ১-২ বাক্যে সংক্ষিপ্ত ও আকর্ষণীয় তথ্য লিখবে প্রমিত বাংলায়। নিচের বিষয়গুলো সম্প্রতি ব্যবহৃত হয়েছে, এড়িয়ে চলো: ${recentTopics}। শুধুমাত্র বৈধ JSON আকারে উত্তর দাও: {"title":"জানা আছে কি?","content":"...","topic":"সংক্ষিপ্ত বিষয় ট্যাগ (ইংরেজি)"}`;
  userPrompt = 'একটি নতুন চমকপ্রদ তথ্য তৈরি করো।';
} else {
  systemPrompt = `তুমি Questionhut ইউটিউব চ্যানেলের জন্য একটি মিনি এডুকেশনাল স্লাইড তৈরি করো — বাংলাদেশের ইতিহাস, বিজ্ঞান, ভূগোল বা সাধারণ জ্ঞান বিষয়ে। একটি শিরোনাম, একটি উপ-শিরোনাম, এবং ৩-৪টি সংক্ষিপ্ত তথ্যভিত্তিক bullet point লিখবে প্রমিত বাংলায় (প্রতিটি এক লাইনে)। নিচের বিষয়গুলো সম্প্রতি ব্যবহৃত হয়েছে, এড়িয়ে চলো: ${recentTopics}। শুধুমাত্র বৈধ JSON আকারে উত্তর দাও: {"title":"...","subtitle":"...","bullets":["...","...","..."],"source":"সূত্র: ...","topic":"সংক্ষিপ্ত বিষয় ট্যাগ (ইংরেজি)"}`;
  userPrompt = 'একটি নতুন তথ্যমূলক মিনি স্লাইড তৈরি করো।';
}

return { json: { cardType, systemPrompt, userPrompt } };

const cardType = $('Pick Card Type').first().json.cardType;
const content = JSON.parse($json.choices[0].message.content);

const staticData = $getWorkflowStaticData('global');
if (!Array.isArray(staticData.usedTopics)) staticData.usedTopics = [];
if (content.topic) {
  staticData.usedTopics.push(content.topic);
  if (staticData.usedTopics.length > 30) staticData.usedTopics.shift();
}

const clip = (s, n) => (s || '').length > n ? (s || '').slice(0, n - 1) + '…' : (s || '');
let sidecarPayload, ytTitle, ytDescription;
const optLabels = ['ক', 'খ', 'গ', 'ঘ'];

if (cardType === 'mcq') {
  sidecarPayload = { cardType: 'mcq', question: content.question, options: content.options, footer: 'সঠিক উত্তর কমেন্টে লিখুন' };
  ytTitle = clip(`🧠 BCS কুইজ: ${content.question}`, 90) + ' #Shorts';
  const opts = (content.options || []).map((o, i) => `${optLabels[i]}) ${o}`).join('\n');
  ytDescription = `${content.question}\n\n${opts}\n\nসঠিক উত্তর কমেন্টে জানান! ✅\n\nপ্রতিদিন নতুন কুইজ পেতে সাবস্ক্রাইব করুন।\n\n#Questionhut #BCS #Quiz #GK #Shorts`;
} else if (cardType === 'info') {
  sidecarPayload = { cardType: 'info', title: content.title || 'জানা আছে কি?', content: content.content, footer: 'প্রতিদিন নতুন তথ্য পেতে সাবস্ক্রাইব করুন' };
  ytTitle = clip(`💡 ${content.content}`, 90) + ' #Shorts';
  ytDescription = `${content.title || 'জানা আছে কি?'}\n\n${content.content}\n\nপ্রতিদিন নতুন তথ্য পেতে সাবস্ক্রাইব করুন।\n\n#Questionhut #GK #Facts #Shorts`;
} else {
  sidecarPayload = { cardType: 'ppt', title: content.title, subtitle: content.subtitle, bullets: content.bullets, source: content.source || '' };
  ytTitle = clip(`📚 ${content.title}`, 90) + ' #Shorts';
  ytDescription = `${content.title}\n${content.subtitle || ''}\n\n${(content.bullets || []).map(b => '• ' + b).join('\n')}\n\nপ্রতিদিন শিখতে সাবস্ক্রাইব করুন।\n\n#Questionhut #GK #Education #Shorts`;
}

return { json: { sidecarPayload, ytTitle, ytDescription } };
